{"cmd":"python3 - <<'PY'
import re
import json
from pathlib import Path
import pandas as pd
import pdfplumber

pdf_path = Path('/root/employees_backup.pdf')
xlsx_path = Path('/root/employees_current.xlsx')

id_re = re.compile(r'^EMP\d{5}$')

columns = ['ID','First','Last','Dept','Position','Salary','Years','Location','Score']

rows = []
with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        tables = page.extract_tables() or []
        for table in tables:
            if not table:
                continue
            # Determine header
            header = None
            first_row = [c.strip() if isinstance(c, str) else c for c in table[0]]
            if first_row and first_row[0] == 'ID':
                header = first_row
                data_rows = table[1:]
            else:
                header = columns
                data_rows = table
            for row in data_rows:
                if not row:
                    continue
                # Normalize length
                # Pad or trim to header length
                if len(row) < len(header):
                    row = row + [None]*(len(header)-len(row))
                elif len(row) > len(header):
                    row = row[:len(header)]
                rec = dict(zip(header, row))
                emp_id = rec.get('ID')
                if not emp_id or not isinstance(emp_id, str):
                    continue
                emp_id = emp_id.strip()
                if not id_re.match(emp_id):
                    continue
                # Clean values
                rec['ID'] = emp_id
                for key in ['First','Last','Dept','Position','Location']:
                    val = rec.get(key)
                    if val is None:
                        rec[key] = None
                    else:
                        rec[key] = str(val).strip()
                # Salary, Years, Score
                def to_int(val):
                    if val is None:
                        return None
                    if isinstance(val, (int, float)):
                        return int(val)
                    val = str(val).replace(',', '').strip()
                    if val == '':
                        return None
                    return int(float(val))
                def to_float(val):
                    if val is None:
                        return None
                    if isinstance(val, (int, float)):
                        return float(val)
                    val = str(val).replace(',', '').strip()
                    if val == '':
                        return None
                    return float(val)
                rec['Salary'] = to_int(rec.get('Salary'))
                rec['Years'] = to_int(rec.get('Years'))
                rec['Score'] = to_float(rec.get('Score'))
                rows.append(rec)

old_df = pd.DataFrame(rows)
# De-duplicate by ID if any duplicates (keep first)
old_df = old_df.drop_duplicates(subset=['ID'])
old_df = old_df[columns]

new_df = pd.read_excel(xlsx_path)
# Normalize columns
new_df = new_df[columns]
# Clean new_df types
for key in ['First','Last','Dept','Position','Location']:
    new_df[key] = new_df[key].astype(str).str.strip()

new_df['Salary'] = new_df['Salary'].apply(lambda v: int(v) if pd.notna(v) else None)
new_df['Years'] = new_df['Years'].apply(lambda v: int(v) if pd.notna(v) else None)
new_df['Score'] = new_df['Score'].apply(lambda v: float(v) if pd.notna(v) else None)

old_map = {row['ID']: row for row in old_df.to_dict(orient='records')}
new_map = {row['ID']: row for row in new_df.to_dict(orient='records')}

old_ids = set(old_map)
new_ids = set(new_map)

# Deleted employees: in old, not in new
deleted = sorted(old_ids - new_ids)

# Modified
modified = []
for emp_id in sorted(old_ids & new_ids):
    old_rec = old_map[emp_id]
    new_rec = new_map[emp_id]
    for field in columns:
        if field == 'ID':
            continue
        old_val = old_rec.get(field)
        new_val = new_rec.get(field)
        # Normalize NaN to None
        if isinstance(old_val, float) and pd.isna(old_val):
            old_val = None
        if isinstance(new_val, float) and pd.isna(new_val):
            new_val = None
        # Compare numeric with tolerance for Score
        if field == 'Score':
            if old_val is None and new_val is None:
                continue
            # If one is None, compare directly
            if old_val is None or new_val is None:
                pass
            else:
                # Use small tolerance
                if abs(float(old_val) - float(new_val)) < 1e-9:
                    continue
        else:
            if old_val == new_val:
                continue
        if old_val != new_val:
            modified.append({
                'id': emp_id,
                'field': field,
                'old_value': old_val,
                'new_value': new_val,
            })

# Sort modified by id then field
modified.sort(key=lambda r: (r['id'], r['field']))

report = {
    'deleted_employees': deleted,
    'modified_employees': modified,
}

out_path = Path('/root/diff_report.json')
with out_path.open('w') as f:
    json.dump(report, f, indent=2)

print('old rows', len(old_df), 'new rows', len(new_df))
print('deleted', len(deleted), 'modified', len(modified))
print('output', out_path)
PY"}

